selector_to_html = {"a[href=\"#module-summary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Summary<a class=\"headerlink\" href=\"#module-summary\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"example_server_fastmcp/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">example_server_fastmcp<a class=\"headerlink\" href=\"#module-mcp.servers.example_server_fastmcp\" title=\"Link to this heading\">\u00b6</a></h1><p>Example MCP server using FastMCP for haive-dataflow integration.</p>", "a[href=\"mcp_server_manager_v2/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_server_manager_v2<a class=\"headerlink\" href=\"#module-mcp.servers.mcp_server_manager_v2\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Manager V2 - Pydantic-based refactor.</p><p>This module provides a refactored MCPServerManager that inherits from the\nbase server management framework, adding MCP-specific functionality with\nfull Pydantic validation.</p>", "a[href=\"mcp_server_manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_server_manager<a class=\"headerlink\" href=\"#module-mcp.servers.mcp_server_manager\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Manager for Model Context Protocol servers.</p><p>This module provides a robust way to start and manage MCP servers, handling\nthe complexities of stdio transport, process management, and server lifecycle.</p>", "a[href=\"#module-mcp.servers\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">servers<a class=\"headerlink\" href=\"#module-mcp.servers\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Management Package.</p><p>This package provides comprehensive server management infrastructure for Model Context\nProtocol (MCP) servers with full Pydantic validation, type safety, and runtime monitoring.\nThe package has been refactored to use a modern Pydantic-based architecture while maintaining\ncomplete backward compatibility with existing code.</p>", "a[href=\"simple_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">simple_server<a class=\"headerlink\" href=\"#module-mcp.servers.simple_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Simple MCP server that you can easily start and add servers to.</p>", "a[href=\"simple_http_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">simple_http_server<a class=\"headerlink\" href=\"#module-mcp.servers.simple_http_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Simple HTTP MCP server example.</p>", "a[href=\"#usage-examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Usage Examples<a class=\"headerlink\" href=\"#usage-examples\" title=\"Link to this heading\">\u00b6</a></h2><h3>Basic Server Management<a class=\"headerlink\" href=\"#basic-server-management\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"dataflow_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow_server<a class=\"headerlink\" href=\"#module-mcp.servers.dataflow_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Haive Dataflow MCP Server - Provides access to haive-dataflow registry and components.</p>", "a[href=\"#basic-server-management\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Server Management<a class=\"headerlink\" href=\"#basic-server-management\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"dataflow_mcp_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow_mcp_server<a class=\"headerlink\" href=\"#module-mcp.servers.dataflow_mcp_server\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server integrating Haive Dataflow for dynamic tool creation.</p><p>This server demonstrates how to create MCP tools from Haive\u2019s dataflow system,\nexposing dataflow graphs as MCP tools and resources. It integrates with:\n- haive-core: For agent and engine functionality\n- haive-dataflow: For registry and discovery systems\n- haive-tools: For exposing existing tools via MCP</p>", "a[href=\"compatibility/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">compatibility<a class=\"headerlink\" href=\"#module-mcp.servers.compatibility\" title=\"Link to this heading\">\u00b6</a></h1><p>Backward compatibility layer for MCPServerManager migration.</p><p>This module provides a compatibility wrapper that allows existing code\nusing MCPServerManager to work with the new Pydantic-based implementation\nwithout modification.</p>", "a[href=\"models/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">models<a class=\"headerlink\" href=\"#module-mcp.servers.models\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server-specific models extending base server management framework.</p><p>This module provides MCP-specific server configuration and runtime information\nmodels that extend the base server management framework from haive-dataflow.</p>", "a[href=\"#available-classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Available Classes<a class=\"headerlink\" href=\"#available-classes\" title=\"Link to this heading\">\u00b6</a></h2><h3>Manager Classes<a class=\"headerlink\" href=\"#manager-classes\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"non_interactive_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">non_interactive_server<a class=\"headerlink\" href=\"#module-mcp.servers.non_interactive_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Non-interactive MCP server manager that avoids EOF errors.</p>", "a[href=\"#server-implementations\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Server Implementations<a class=\"headerlink\" href=\"#server-implementations\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#http-server-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">HTTP Server Setup<a class=\"headerlink\" href=\"#http-server-setup\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#key-components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Components<a class=\"headerlink\" href=\"#key-components\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"http_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">http_server<a class=\"headerlink\" href=\"#module-mcp.servers.http_server\" title=\"Link to this heading\">\u00b6</a></h1><p>HTTP-based MCP server for haive using FastAPI and SSE transport.</p>", "a[href=\"#configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Configuration<a class=\"headerlink\" href=\"#configuration\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#manager-classes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Manager Classes<a class=\"headerlink\" href=\"#manager-classes\" title=\"Link to this heading\">\u00b6</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
